import { Suspense, useState, useRef, useEffect, useCallback } from 'react'
import type { ReactNode } from 'react'
import { Outlet } from 'react-router'
import { useNavigate, useLocation } from 'react-router'
import { Box, Collapsible, Drawer, Portal } from '@chakra-ui/react'
import type { MenuOpenChangeDetails } from '@chakra-ui/react'
import { BsArrowDownCircle } from 'react-icons/bs'

import { MenuProvider } from '~/ui/layout/menu'
import { MyMenu } from './MyMenu'
import { MyYesButton, MyCloseButton } from '~/ui/parts/MyButton'
import { MyScrollArea } from '~/ui/parts/MyScrollArea'


/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'



type MethodDrawerProp = {
  open: boolean;
  onDrawerOpenChange: (e: MenuOpenChangeDetails) => void;
}

export const useMethodDrawer = (pathOnClose: string, pathOnOpen: (kind: string, name: string) => string) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [open, setOpen] = useState<boolean>(false);
  
  useEffect(() => {
    setOpen((location.pathname.endsWith(pathOnClose) || location.pathname.endsWith(`${pathOnClose}/`)) ? false : true);
  }, [location, setOpen]);
  
  const onDrawerOpenChange = useCallback((e: MenuOpenChangeDetails) => {
    if (e.open) {
      setOpen(true);
    } else {
      navigate(pathOnClose);
      setOpen(false);
    }
  }, [pathOnClose, setOpen]);
  const createOnOpenDrawer = useCallback((kind: string, name: string) => () => {
    navigate(pathOnOpen(kind, name));
    setOpen(true);
  }, [navigate, pathOnOpen, setOpen]);
  
  return {
    open: open,
    onDrawerOpenChange: onDrawerOpenChange,
    openDrawer: createOnOpenDrawer
  }
}


export function MethodDrawer(prop: MethodDrawerProp) {
  const { open, onDrawerOpenChange } = prop;

  return (
    <Drawer.Root open={open} onOpenChange={onDrawerOpenChange}>
      <Portal>
        <Drawer.Backdrop />
        <Drawer.Positioner>
          <MenuProvider>
            <Drawer.Content css={styles.drawerContent} lgDown={{ '--drawer-padding-inline': '0.5em' }}>
              <Suspense fallback={<MethodDrawerSuspense />}>
                <Outlet />
              </Suspense>
              <Box className='control-buttons'>
                <MyMenu mode='drawer' />
                <Drawer.CloseTrigger unstyled={true} asChild>
                  <MyCloseButton size='sm' />
                </Drawer.CloseTrigger>
              </Box>
            </Drawer.Content>
          </MenuProvider>
        </Drawer.Positioner>
      </Portal>
    </Drawer.Root>
  )
}


type MethodDrawerContentProp = {
  title: ReactNode;
  prelude: ReactNode;
  children: ReactNode;
}
export function MethodDrawerContent(prop: MethodDrawerContentProp) {
  const { title, prelude, children } = prop;
  
  const [openPrelude, setOpenPrelude] = useState<boolean>(false);
  const preludeTriggerRef = useRef<HTMLButtonElement | null>(null);
  const handlerClickPrelude = () => setOpenPrelude((curOpen) => {
    if (!curOpen) {
      preludeTriggerRef.current?.focus({ preventScroll: true });
    }
    return true;
  });
  
  return (
    <>
      <Drawer.Header className='header' flexDirection='column' alignItems='flex-start' gap='0'>
        <Drawer.Title as='h2' className='title'>{title}</Drawer.Title>
        {/* buttonのサイズはchakra-uiデフォルトのrem指定で、collapseHeightもそれに併せる。後々button共々emへ修正するかも */}
        <Collapsible.Root className='prelude-area' collapsedHeight='2.25rem' maxHeight='80dvh'
          open={openPrelude} onOpenChange={(e) => setOpenPrelude(e.open)}
          >
          <Collapsible.Trigger asChild>
            <MyYesButton className='prelude-toggled' size='sm' ref={preludeTriggerRef}>
              <span className='prelude-title'>
                <Collapsible.Context>
                  {(api) => (api.open ? '折りたたむ' : '続きを読む')}
                </Collapsible.Context>
              </span>
              <Collapsible.Indicator
                transition='transform 0.2s'
                _open={{ transform: 'rotate(180deg)' }}
                >
                <BsArrowDownCircle />
              </Collapsible.Indicator>
            </MyYesButton>
          </Collapsible.Trigger>
          <Collapsible.Content
            className='prelude' w='100%'
            _closed={{
              shadow: 'inset 0 -12px 12px -12px var(--shadow-color)',
              shadowColor: 'blackAlpha.500',
            }}
            onClick={handlerClickPrelude}
            >
            <MyScrollArea.Normal hiddenBar={!openPrelude}>
              {prelude}
            </MyScrollArea.Normal>
          </Collapsible.Content>
        </Collapsible.Root>
      </Drawer.Header>
      <Drawer.Body className='body'>
        {children}
      </Drawer.Body>
    </>
  )
}



import { Skeleton, SkeletonText } from '@chakra-ui/react'

