import { StrictMode, Suspense } from 'react'
import { createRoot } from 'react-dom/client'
import { ErrorBoundary, getErrorMessage } from 'react-error-boundary'
import { ChakraProvider } from '@chakra-ui/react'
import { MathJaxContext } from 'better-react-mathjax'
import Bowser from 'bowser'

import { SettingsProvider } from './settings'

import './index.css'
import App from './App.tsx'
import system from './theme.ts'


const curEnv = checkBrowserRequirements();

if (curEnv.isValid) {
createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <Suspense fallback={
        <>
          <style>{`
            .app-suspense-area {
              width: 100%;
              height: 100%;
              background: var(--bg, #fff);
              opacity: 0.5;
              
              transition: opacity 5s ease;
              
              @starting-style {
                opacity: 0;
              }
            }
          `}</style>
          <div className='app-suspense-area'></div>
        </>
      }>
      <ErrorBoundary
        fallbackRender={({ error/*, resetErrorBoundary*/ }) => {
          const info = (() => {
            if (error instanceof DOMException) {
              const msg = 'ご使用のブラウザでは、このページを表示できません。';
              if (error.name === 'SecurityError') return {
                msg: msg,
                detail: 'プライバシー＆セキュリティの設定で、Javascriptなどの動作が制限されている可能性があります。'
              };
            }
            return {
              msg: 'すみません。想定外のエラーが発生したため、表示処理を中断しました。',
              detail: 'ページのメンテナンス中の可能性があります。明日もう一度アクセスして頂けると助かります。',
              repletion: getErrorMessage(error)
            };
          })();
          return (
            <div role='alert'>
              <p>{info.msg}</p>
              <p>{info.detail}</p>
              <pre>{info.repletion}</pre>
            </div>
          )
        }}>
        <ChakraProvider value={system}>
          <SettingsProvider>
            <MathJaxContext>
              <App />
            </MathJaxContext>
          </SettingsProvider>
        </ChakraProvider>
      </ErrorBoundary>
    </Suspense>
  </StrictMode>,
)
} else {
  const isValidType = (curEnv.browserInfo.name === 'Chrome') ||
                        (curEnv.browserInfo.name === 'Microsoft Edge') ||
                        (curEnv.browserInfo.name === 'Firefox') ||
                        (curEnv.browserInfo.name === 'Safari');
  const message = isValidType ? `
    ${curEnv.browserInfo.name} のバージョンを、最新へアップデートした後に、<br/>
    このページの再読み込みをお願いします。
  ` : `
    ${curEnv.browserInfo.name} はサポートしていないブラウザなので、<br/>
    Chrome、Microsoft Edge、Firefox、または Safari での表示をお願いします。
  `;
  
  const rootElement = document.getElementById('root');
  if (rootElement) {
    rootElement.innerHTML = `
      <div style='text-align: center;'>
        <h2>ご使用のブラウザでは、表示することができません</h2>
        <p>
          ${message}
        </p>
      </div>
    `;
  }
}


/*
 基本は:
  https://ja.vite.dev/guide/build.html
 ページ作成で使っている機能:
 -JS
  https://developer.mozilla.org/ja/docs/Web/API/Window/structuredClone#ブラウザーの互換性
 -css
  https://caniuse.com/mdn-css_at-rules_container
 
 */
function checkBrowserRequirements() {
  const browser = Bowser.getParser(window.navigator.userAgent);
  return {
    browserInfo: browser.getBrowser(),
    isValid: browser.satisfies({
      chrome: ">=111",
      edge: ">=111",
      firefox: ">=114",
      safari: ">=16.4",
    })
  };
}
