type SeoInfo = {
  pathname: string;
  title: string;
  metaDescription: string;
  breadcrumbTrail?: string;
}
type SimpleComponentProp = {
  children: ReactNode;
}
function SeoController(prop: SimpleComponentProp) {
  const { children } = prop;
  const seoList = [
    {
      pathname: paths.block.path(),
      title: 'LEGO(レゴ),LaQ(ラキュー)で楽しもう：がみ〜工房-工作室',
      metaDescription: '子供たちのワクワクを、LEGO(レゴ)・LaQ(ラキュー)での工作で応援するページです。工作が好き⇒腕試しにトライ。何すれば...⇒レシピの手順でチャレンジ。好みの方法で楽しんで欲しいです。',
      breadcrumbTrail: `[
        {
          "@type": "ListItem",
          "position": 1,
          "name": "LEGO(レゴ)のレシピ集",
          "item": "https://gamii-site.github.io/crafts/block/method/lego"
        },
        {
          "@type": "ListItem",
          "position": 2,
          "name": "LaQ(ラキュー)のレシピ集",
          "item": "https://gamii-site.github.io/crafts/block/method/laq"
        }
      ]`
    },
    {
      pathname: paths.block.method.lego.path(),
      title: 'LEGO(レゴ)のレシピ集：がみ〜工房-工作室',
      metaDescription: '子供たちのワクワクを、LEGO(レゴ)・LaQ(ラキュー)での工作で応援するページです。LEGO(レゴ)のアイデアをまとめました。参考になれれば嬉しいです。',
      breadcrumbTrail: undefined,
    },
    {
      pathname: paths.block.method.laq.path(),
      title: 'LaQ(ラキュー)のレシピ集：がみ〜工房-工作室',
      metaDescription: '子供たちのワクワクを、LEGO(レゴ)・LaQ(ラキュー)での工作で応援するページです。LaQ(ラキュー)のアイデアをまとめました。参考になれれば嬉しいです。',
      breadcrumbTrail: undefined,
    },
    {
      pathname: paths.beads.path(),
      title: 'アイロンビーズ３D(立体)で楽しもう：がみ〜工房-工作室',
      metaDescription: '子供たちのワクワクを、アイロンビーズでの３D工作で応援するページです。工作が好き⇒腕試しにトライ。何すれば...⇒レシピの手順でチャレンジ。好みの方法で楽しんで欲しいです。',
      breadcrumbTrail: `[
        {
          "@type": "ListItem",
          "position": 1,
          "name": "アイロンビーズ３D(立体)のレシピ集",
          "item": "https://gamii-site.github.io/crafts/block/method/lego"
        },
      ]`
    },
    {
      pathname: paths.beads.method.iron.path(),
      title: 'アイロンビーズ３D(立体)のレシピ集：がみ〜工房-工作室',
      metaDescription: '子供たちのワクワクを、アイロンビーズでの３D工作で応援するページです。アイロンビーズ３Dのアイデアをまとめました。参考になれれば嬉しいです。',
      breadcrumbTrail: undefined,
    },
  ];
  const [ seo, setSeo ] = useState<SeoInfo>(seoList[0]);
  const location = useLocation();
  useEffect(() => {
    setSeo((postSeo) => {
      const newSeo = seoList.find((argSeo) => argSeo.pathname === location.pathname);
      return (newSeo && newSeo.pathname !== postSeo.pathname) ? newSeo : postSeo;
    });
  }, [location.pathname]);
  
  /*
   以下をpath毎に追加。
   head部に
     <title>、<meta name="description">の、ページ情報
     <meta property="og:xxx" content="xxx">の、OGP（Open Graph Protocol）情報
   body部に
     <script type="application/ld+json">の、リッチリザルト パンくずリスト情報
   */
  return (
    <>
      <Title>{seo.title}</Title>
      <Meta 
        name='description' 
        content={seo.metaDescription}
        />
      <OpenGraph
        title={seo.title}
        type='website'
        image={`${baseUrl}/sheepicon.svg`}
        url={`${baseUrl}${seo.pathname}`}
        description={seo.metaDescription}
        siteName='がみ〜工房-工作室'
        locale='ja_JP'
        />
      {seo.breadcrumbTrail && <script type='application/ld+json'>{`
        {
          "@context": "https://schema.org",
          "@type": "BreadcrumbList",
          "itemListElement": ${seo.breadcrumbTrail}
        }
      `}</script>}
      {children}
    </>
  )
}

import { useNavigate, useSearchParams } from 'react-router'

function AccessBySpecifiedPath(prop: SimpleComponentProp) {
  const { children } = prop;
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  
  useEffect(() => {
    // 各path配下のindex.html や 404.html からの redirect であれば、元々指定されたpathへ遷移する
    // sliceで終端を-1にしているのは、Github Pagesが/crafts/blockへアクセスすると/crafts/block/に補正してしまうので、最後の要素を除いている
    if (searchParams?.get('path')?.includes(import.meta.env.BASE_URL)) {
      const redirectUrl = searchParams?.get('path')?.split('/').slice(2, -1).join('/');
      const hash = searchParams?.get('hash');
      if (redirectUrl) {
        navigate({ pathname:`/${redirectUrl}`, hash: hash ? `#${hash}` : undefined });
      }
    }
  }, []);
  
  return (
    <>
      {children}
    </>
  )
}

function App() {
  useEffect(() => {
    const targetLink = document.querySelector('link[rel="canonical"]');
    if (targetLink) {
      targetLink.remove();
    }
  }, []);
  
  return (
    <MenuProvider>
      <RouterProvider router={router} />
    </MenuProvider>
  )
}

export default App



import { useRouteError, isRouteErrorResponse, useLocation, NavLink } from 'react-router'
import { Link } from '@chakra-ui/react'

function RootErrorBoundary() {
  const error = useRouteError();
  const location = useLocation();
  
  // react-router関連のエラーでないなら、throwして上位のErrorBoundaryに委ねる
  if (!isRouteErrorResponse(error)) throw error;
  
  const Core = (error.status === 404) ? () => {
    return (
    <>
      <h2>指定されたURLパスが存在しません。</h2>
      <p>
        URLパス：{location.pathname}
      </p>
    </>
    )
  } : () => {
    return (
    <>
      <h2>指定されたURLが正しくありません。</h2>
      <p>{error.status} {error.statusText}</p>
      <p>{error.data}</p>
    </>
    )
  };
  return (
    <div style={{textAlign: 'center'}}>
      <Core />
      <br/>
      <p>
        ↓のリンクをクリックして、TOP画面からご参照ください。<br/>
        <Link asChild colorPalette='teal' variant='underline'>
          <NavLink to='/'>[ TOPへ ]</NavLink>
        </Link>
      </p>
    </div>
  )
  /*
404 Not Found
Error: No route matches URL "/crafts/block/method/legoo/tin-power"
  */
}

